DELETE FROM "airtable"."projects" as d WHERE EXISTS (SELECT 1 FROM "airtable_staging"."projects" as s WHERE d."id" = s."id")
INSERT INTO "airtable"."projects"("id", "created_time", "fields__project_id", "_dlt_load_id", "_dlt_id")                  SELECT "id", "created_time", "fields__project_id", "_dlt_load_id", "_dlt_id"                     FROM (                         SELECT ROW_NUMBER() OVER (partition BY "id" ORDER BY (SELECT NULL)) AS _dlt_dedup_rn, "id", "created_time", "fields__project_id", "_dlt_load_id", "_dlt_id"                         FROM "airtable_staging"."projects"                     ) AS _dlt_dedup_numbered WHERE _dlt_dedup_rn = 1 AND (1 = 1)          